mapper.select:
SELECT ID, LEAGUE_NAME FROM (
    SELECT ID, LEAGUE_NAME, ROW_NUMBER() OVER (ORDER BY TREE_SORTS, TREE_SORT, ID) AS RN
    FROM LEAGUE_ORGANIZATION
    WHERE ORG_IDENTITY = #{orgIdentity} AND (PARENT_ID IS NULL OR PARENT_ID <> '-1')
) WHERE RN > #{offset} AND RN <= #{limit}
ORDER BY RN

SELECT LEAGUE_ID, HYLX, TO_CHAR(HYRQ, 'YYYY-MM') AS MEETING_MONTH, COUNT(*) AS MEETING_COUNT
FROM DYN_TWSHYK
WHERE ORG_IDENTITY = #{orgIdentity}
  AND HYRQ >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
  AND HYRQ < TO_DATE(#{endDate}, 'YYYY-MM-DD')
  AND HYLX IN ('支部委员会', '团课', '支部大会')
AND LEAGUE_ID = #{leagueId}

    AND LEAGUE_ID IN
    #{id}

GROUP BY LEAGUE_ID, HYLX, TO_CHAR(HYRQ, 'YYYY-MM')
